CREATE POLICY "Website admins manage slide images" ON storage.objects FOR ALL TO authenticated USING (bucket_id = 'website-slides' AND software.is_admin('00000000-0000-0000-0000-000000000001'::uuid)) WITH CHECK (bucket_id = 'website-slides' AND (storage.foldername(name))[1] = 'landing' AND lower(storage.extension(name)) IN ('jpg', 'jpeg', 'png', 'webp', 'avif') AND software.is_admin('00000000-0000-0000-0000-000000000001'::uuid));
CREATE POLICY "Visitors read published slide images" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'website-slides' AND EXISTS (SELECT 1 FROM software.site_content s CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(s.content->'heroSlides') = 'array' THEN s.content->'heroSlides' ELSE '[]'::jsonb END) slide WHERE s.id = 'landing' AND slide->>'path' = storage.objects.name));